from pathlib import Path
import json,re
root=Path('docs/design/mobile-pdf-annotation-list-v1');root.mkdir(exist_ok=True)
assert not (root/'index.html').exists(), 'Frozen source must not be replaced'
base=Path('docs/design/mobile-pdf-navigation-v2/index.html').read_text(encoding='utf-8').split('</style>')[0]
css='''
/* annotation-list */
.pdf-notes-panel,.pdf-notes-panel.is-organizing{--notes-error:#a13e32;position:absolute;inset:0;z-index:10;height:100%;min-height:0;border:0;border-radius:0;box-shadow:none;display:flex;flex-direction:column;overflow:hidden;background:var(--bg);color:var(--ink)}
.pdf-notes-surface{display:flex;flex:1;flex-direction:column;min-height:0}.pdf-notes-heading{display:flex;align-items:center;gap:8px;min-height:64px;padding:7.5px 8px;border-bottom:1px solid var(--line);flex:none}.pdf-notes-heading h1{flex:1;min-width:0;margin:0;font-size:1.25rem;line-height:1.5;letter-spacing:normal;font-weight:700;overflow-wrap:anywhere}.pdf-notes-back,.pdf-notes-more,.pdf-notes-close{display:grid;place-items:center;flex:0 0 48px;width:48px;height:48px;padding:0;border:0;background:transparent;color:var(--muted)}
.pdf-notes-context{display:flex;gap:12px;align-items:start;flex:none;padding:12px 16px}.pdf-notes-context p{flex:1;min-width:0;margin:0;font-size:.8125rem;line-height:1.5384615385;color:var(--muted);overflow-wrap:anywhere}.pdf-notes-context span{flex:none;color:var(--muted);font-size:.8125rem;line-height:1.5384615385}
.pdf-notes-body{flex:1;min-height:0;padding:16px;overflow:auto;overscroll-behavior:contain}.pdf-annotation-search{display:flex;align-items:stretch;gap:8px}.pdf-annotation-query-wrap{flex:1;position:relative;min-width:0}.pdf-annotation-query-wrap>svg{position:absolute;left:12px;top:50%;transform:translateY(-50%);color:var(--muted);pointer-events:none}.pdf-annotation-query-wrap input{display:block;width:100%;min-width:0;min-height:48px;padding:10px 40px;font:inherit;font-size:1rem;line-height:1.5;color:var(--ink);background:var(--panel);border:1px solid var(--line);border-radius:10px;appearance:none}.pdf-annotation-query-wrap input::placeholder{color:var(--muted);opacity:1}.pdf-annotation-query-wrap input::-webkit-search-cancel-button{display:none}.pdf-annotation-query-clear{position:absolute;right:0;top:0;width:40px;height:100%;border:0;background:transparent;color:var(--muted)}.pdf-annotation-filter-button{display:grid;place-items:center;flex:0 0 48px;width:48px;min-height:48px;padding:0;border:1px solid var(--line);border-radius:10px;background:var(--surface);color:var(--muted)}.pdf-annotation-filter-button.is-active{background:var(--primary-soft);color:var(--primary);border-color:var(--primary)}
.pdf-applied-filters{display:flex;align-items:center;margin-top:12px;border:1px solid var(--line);border-radius:10px;background:var(--primary-soft)}.pdf-applied-filters>button:first-child{flex:1;min-width:0;min-height:48px;padding:8px 12px;text-align:left;border:0;background:transparent;color:var(--ink);font:inherit;font-size:.875rem;line-height:1.5;overflow-wrap:anywhere}.pdf-applied-filters>button:last-child{width:48px;height:48px;flex:none;border:0;background:transparent;color:var(--muted)}
.pdf-annotation-count{margin:14px 0 10px;color:var(--muted);font-size:.875rem;line-height:1.5}.pdf-annotation-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:12px}.pdf-annotation-list .pdf-note-card{margin:0;border:1px solid var(--line);border-radius:12px;overflow:hidden;background:var(--surface)}.pdf-annotation-link{position:relative;display:block;width:100%;min-height:96px;padding:12px 42px 12px 14px;border:0;background:transparent;color:var(--ink);text-align:left;font:inherit}.pdf-annotation-meta{display:flex;align-items:center;gap:8px;font-size:.8125rem;line-height:1.5384615385;color:var(--muted)}.pdf-annotation-meta small{margin-left:auto;font-size:.8125rem;line-height:1.5384615385}.pdf-annotation-link strong{display:block;margin-top:6px;font-size:1rem;line-height:1.5;font-weight:650;overflow-wrap:anywhere}.pdf-annotation-secondary{display:block;margin-top:4px;color:var(--muted);font-size:.875rem;line-height:1.5;overflow-wrap:anywhere}.pdf-annotation-link>svg{position:absolute;right:12px;top:50%;transform:translateY(-50%);color:var(--muted)}.pdf-annotation-chosen{display:block;margin-top:6px;font-size:.8125rem;line-height:1.5;color:var(--primary)}
.pdf-swatch{display:inline-block;flex:none;width:16px;height:16px;border-radius:4px}.color-yellow{background:#ffe16a}.color-green{background:#88bc7c}.color-pink{background:#ed9cb5}.color-blue{background:#88b9ed}
.pdf-notes-empty-state{text-align:center;padding:40px 12px;color:var(--muted)}.pdf-notes-empty-state>svg{color:var(--primary)}.pdf-notes-empty-state h2{margin:16px 0;font-size:1.125rem;line-height:1.5;color:var(--ink)}.pdf-notes-empty-state>.button{margin-top:4px}.pdf-notes-footer{display:flex;flex:none;gap:8px;padding:12px 16px calc(12px + env(safe-area-inset-bottom));border-top:1px solid var(--line);background:var(--bg);max-height:45dvh;overflow:auto}.pdf-notes-footer>.button{flex:1;min-width:0;min-height:48px;padding:11px 10px;border-radius:10px;font-size:.875rem;line-height:1.7142857143;font-weight:400}
.pdf-annotation-detail-meta{display:flex;align-items:center;gap:8px;margin-bottom:16px;font-size:.875rem;line-height:1.5;color:var(--muted)}.pdf-annotation-detail-meta .pdf-notes-more{margin-left:auto}.pdf-annotation-detail section+section{margin-top:24px}.pdf-annotation-detail h2{margin:0 0 10px;font-size:1rem;line-height:1.5;font-weight:650}.pdf-annotation-detail blockquote{margin:0;border-left:3px solid var(--primary-soft);padding-left:12px;font-size:1rem;line-height:1.75;white-space:pre-wrap;overflow-wrap:anywhere}.pdf-annotation-detail p{margin:0;font-size:1rem;line-height:1.75;white-space:pre-wrap;overflow-wrap:anywhere}
.pdf-annotation-filter-task fieldset{min-inline-size:0;border:0;padding:0;margin:0}.pdf-annotation-filter-task legend{margin:0 0 12px;padding:0;font-size:1rem;line-height:1.5;font-weight:650}.pdf-filter-choices{border:1px solid var(--line);border-radius:12px;overflow:hidden;background:var(--surface)}label.pdf-filter-choice{display:flex;align-items:center;gap:12px;min-height:56px;padding:12px 14px;margin:0;border-bottom:1px solid var(--line);font-size:1rem;line-height:1.5}label.pdf-filter-choice:last-child{border:0}.pdf-filter-choice span{flex:1;min-width:0;overflow-wrap:anywhere}.pdf-annotation-filter-task .pdf-filter-choice input,.pdf-annotation-filter-task .pdf-filter-switch input{appearance:auto;flex:none;width:20px;min-height:0;height:20px;margin:0;padding:0;accent-color:var(--primary)}label.pdf-filter-switch{display:flex;align-items:center;gap:12px;min-height:56px;padding:12px 14px;margin:20px 0 0;border:1px solid var(--line);border-radius:12px;background:var(--surface);font-size:1rem;line-height:1.5}.pdf-filter-switch>span{flex:1;min-width:0}.pdf-filter-switch small{display:block;color:var(--muted);font-size:.875rem;line-height:1.5;margin-top:4px}
.pdf-deletion-recovery{display:flex;align-items:center;gap:12px;margin:0 0 16px;padding:12px;border-radius:10px;background:var(--primary-soft);font-size:.875rem;line-height:1.5}.pdf-deletion-recovery>div{flex:1;min-width:0}.pdf-deletion-recovery strong{display:block;font-size:.875rem}.pdf-deletion-recovery p{margin:4px 0 0;overflow-wrap:anywhere}.pdf-deletion-recovery>.button{flex:none;padding:10px;font-size:.8125rem;min-height:48px}.pdf-notes-error{color:var(--notes-error);font-size:.875rem;line-height:1.6;overflow-wrap:anywhere}
.pdf-notes-layer{position:absolute;z-index:16;inset:0;display:grid;place-items:center;padding:16px;background:#14261d66}.pdf-notes-dialog{display:flex;flex-direction:column;width:min(100%,400px);max-height:100%;min-height:0;border:1px solid var(--line);border-radius:16px;overflow:hidden;background:var(--bg);box-shadow:0 12px 40px #14261d26}.pdf-notes-dialog-header{display:flex;align-items:center;gap:8px;min-height:64px;padding:7.5px 8px 7.5px 16px;border-bottom:1px solid var(--line);background:var(--bg);flex:none}.pdf-notes-dialog-header h2{flex:1;min-width:0;margin:0;font-size:1.25rem;line-height:1.5;letter-spacing:normal;font-weight:700;overflow-wrap:anywhere}.pdf-notes-dialog-body{padding:16px;overflow:auto;overscroll-behavior:contain;min-height:0}.pdf-annotation-target{margin:0 0 16px;overflow-wrap:anywhere}.pdf-annotation-target strong{display:block;font-size:1rem;line-height:1.5;font-weight:650}.pdf-annotation-target small{display:block;margin-top:4px;font-size:.875rem;line-height:1.5;color:var(--muted)}.pdf-notes-dialog-choice{display:flex;align-items:center;gap:12px;width:100%;min-height:56px;padding:12px 4px;border:0;border-top:1px solid var(--line);background:transparent;color:var(--ink);font:inherit;font-size:1rem;line-height:1.5;text-align:left;overflow-wrap:anywhere}.pdf-notes-dialog-choice svg{flex:none}.pdf-notes-dialog-choice.danger{color:var(--notes-error)}.pdf-delete-copy{margin:0;font-size:.875rem;line-height:1.6;overflow-wrap:anywhere}.pdf-delete-copy+p{margin-top:12px}.pdf-notes-dialog-footer{display:flex;flex:none;gap:8px;padding:12px 16px;border-top:1px solid var(--line);background:var(--bg);max-height:45dvh;overflow:auto}.pdf-notes-dialog-footer>.button{flex:1;min-width:0;min-height:48px;padding:11px 10px;border-radius:10px;font-size:.875rem;line-height:1.7142857143;font-weight:400}.pdf-notes-dialog-footer>.danger-button{background:var(--notes-error);border-color:var(--notes-error);color:var(--bg)}
@media(max-width:340px){.pdf-notes-context{flex-wrap:wrap;gap:4px 12px}.pdf-notes-context p{flex-basis:100%}.pdf-annotation-meta{flex-wrap:wrap}.pdf-annotation-meta small{margin-left:0}.pdf-notes-footer,.pdf-notes-dialog-footer{flex-direction:column}.pdf-notes-footer>.button,.pdf-notes-dialog-footer>.button{flex:none}.pdf-notes-dialog-header h2{font-size:1.125rem}.pdf-deletion-recovery{flex-wrap:wrap}.pdf-deletion-recovery>.button{margin-left:auto}}
@media(max-height:400px){.pdf-notes-heading{min-height:49px;padding:0 8px}.pdf-notes-heading h1{font-size:1rem}.pdf-notes-context{display:none}.pdf-notes-body{padding:12px}.pdf-notes-layer{padding:8px}.pdf-notes-dialog-header{min-height:49px;padding:0 8px 0 12px}.pdf-notes-dialog-header h2{font-size:1rem}.pdf-notes-dialog-body{padding:12px}.pdf-notes-footer,.pdf-notes-dialog-footer{flex-direction:row;padding:8px 12px}.pdf-notes-footer>.button,.pdf-notes-dialog-footer>.button{flex:1;padding:8px 6px;font-size:.75rem;line-height:1.5}}
/* end annotation-list */
'''
icons={}
for key,file in {'back':'arrow-left','help':'circle-question-mark','more':'ellipsis','search':'search','filter':'list-filter','close':'x','chevron':'chevron-right','comment':'message-square','notebook':'notebook-pen','refresh':'refresh-cw','trash':'trash-2','check':'square-check','undo':'undo-2'}.items():
 source=Path('node_modules/lucide-vue-next/dist/esm/icons/'+file+'.js').read_text(encoding='utf-8');nodes=re.findall(r'\[\s*"(path|circle|line|polyline|rect)"\s*,\s*\{\s*([^}]+)\s*\}\s*\]',source,re.S);assert len(nodes)==len(re.findall(r'\[\s*"(?:path|circle|line|polyline|rect)"',source)),file
 icons[key]=''.join('<'+tag+' '+' '.join(k+'="'+v+'"' for k,v in re.findall(r'(\w+):\s*"([^"]*)"',fields) if k!='key')+' />' for tag,fields in nodes)
script=r'''
const screen=new URLSearchParams(location.search).get('screen')||'list',icons=ICONS,icon=(name,size=22)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]}</svg>`;
const colors={yellow:'黄色',green:'绿色',pink:'粉色',blue:'蓝色'},all=[{page:1,kind:'高亮',color:'green',comment:'为重要的想法留出空间。',quote:'Make room for ideas'},{page:1,kind:'高亮',color:'yellow',comment:'记住上次读到的位置。',quote:'Keep your place'},{page:3,kind:'评论',color:'blue',comment:'下次从这里继续。',quote:''}],detail=['detail','actions','delete'].includes(screen),filters=['filters','filters-edited'].includes(screen),empty=screen==='empty',missing=screen==='no-match',filtered=screen==='filtered',undo=screen==='undo',items=empty||missing?[]:undo?all.slice(1):filtered?[all[0]]:all,query=filtered?'ideas':missing?'不存在的想法':'',total=empty?0:undo?2:3,mode=detail?'detail':filters?'filters':'list';
const card=a=>`<li class="pdf-note-card"><button class="pdf-annotation-link"><span class="pdf-annotation-meta"><i class="pdf-swatch color-${a.color}"></i><span>第 ${a.page} 页 · ${a.kind}</span><small>${colors[a.color]}</small></span><strong>${a.comment||a.quote}</strong>${a.comment&&a.quote?`<span class="pdf-annotation-secondary">${a.quote}</span>`:''}${icon('chevron',20)}</button></li>`;
let body=detail?`<article class="pdf-annotation-detail"><div class="pdf-annotation-detail-meta"><i class="pdf-swatch color-green"></i><span>绿色</span><button class="pdf-notes-more">${icon('more')}</button></div><section><h2>原文摘录</h2><blockquote>Make room for ideas</blockquote></section><section><h2>我的想法</h2><p>为重要的想法留出空间。</p></section></article>`:filters?`<div class="pdf-annotation-filter-task"><fieldset><legend>标记颜色</legend><div class="pdf-filter-choices">${Object.entries({all:'全部颜色',...colors}).map(([c,t])=>`<label class="pdf-filter-choice">${c==='all'?'':`<i class="pdf-swatch color-${c}"></i>`}<span>${t}</span><input type="radio" name="filter-color" ${c===(screen==='filters-edited'?'green':'all')?'checked':''}></label>`).join('')}</div></fieldset><label class="pdf-filter-switch"><span>仅当前页<small>第 1 页</small></span><input type="checkbox" ${screen==='filters-edited'?'checked':''}></label></div>`:`${undo?`<aside class="pdf-deletion-recovery"><div><strong>已删除第 1 页批注</strong><p>为重要的想法留出空间。</p></div><button class="button">${icon('undo',18)}撤销删除</button></aside>`:''}<div class="pdf-annotation-search"><div class="pdf-annotation-query-wrap">${icon('search',20)}<input type="search" value="${query}" placeholder="查找摘录或想法">${query?`<button class="pdf-annotation-query-clear">${icon('close',18)}</button>`:''}</div><button class="pdf-annotation-filter-button ${filtered?'is-active':''}">${icon('filter')}</button></div>${filtered?`<div class="pdf-applied-filters"><button>绿色 · 仅第 1 页</button><button>${icon('close',18)}</button></div>`:''}<p class="pdf-annotation-count">${query?`找到 ${items.length} 条 · 共 ${total} 条`:`全部 ${total} 条`}</p>${items.length?`<ol class="pdf-annotation-list">${items.map(card).join('')}</ol>`:`<div class="pdf-notes-empty-state">${icon(empty?'comment':'search',38)}<h2>${empty?'还没有批注':'没有匹配的批注'}</h2>${missing?'<button class="button">清空搜索与筛选</button>':''}</div>`}`;
const footer=detail?'<button class="button primary-button">回到原文</button><button class="button">编辑批注</button>':filters?'<button class="button">重置</button><button class="button primary-button">应用筛选</button>':'<button class="button primary-button">添加本页评论</button>';
const dialog=['actions','delete'].includes(screen)?`<div class="pdf-notes-layer"><section class="pdf-notes-dialog"><header class="pdf-notes-dialog-header"><h2>${screen==='delete'?'删除批注？':'这条批注的操作'}</h2><button class="pdf-notes-close">${icon('close')}</button></header><div class="pdf-notes-dialog-body"><p class="pdf-annotation-target"><strong>为重要的想法留出空间。</strong><small>第 1 页 · 高亮</small></p>${screen==='delete'?'<p class="pdf-delete-copy">删除这条批注？原 PDF 和已生成的笔记仍保留。</p>':`<button class="pdf-notes-dialog-choice">${icon('check',20)}选入阅读笔记</button><button class="pdf-notes-dialog-choice danger">${icon('trash',20)}删除批注</button><button class="pdf-notes-dialog-choice">${icon('refresh',20)}重新读取批注</button>`}</div><footer class="pdf-notes-dialog-footer"><button class="button">${screen==='delete'?'保留批注':'返回详情'}</button>${screen==='delete'?'<button class="button danger-button">确认删除</button>':''}</footer></section></div>`:'';
document.querySelector('.phone').innerHTML=`<section class="pdf-notes-panel"><div class="pdf-notes-surface"><header class="pdf-notes-heading"><button class="pdf-notes-back">${icon('back')}</button><h1>${detail?'批注详情':filters?'筛选批注':'批注'}</h1>${mode==='list'?`<button class="pdf-notes-more">${icon('more')}</button>`:''}<button class="mobile-help-trigger">${icon('help',20)}</button></header><div class="pdf-notes-context"><p>阅读导航.pdf</p><span>${detail?'第 1 页 · 高亮':'当前第 1 页'}</span></div><div class="pdf-notes-body">${body}</div><footer class="pdf-notes-footer">${footer}</footer></div>${dialog}</section>`;
'''.replace('ICONS',json.dumps(icons,ensure_ascii=False))
(root/'index.html').write_text(base+css+'</style><div class="phone"></div><script>'+script+'</script></html>',encoding='utf-8')
capture=Path('scripts/capture-mobile-pdf-annotation-editor-design.mjs').read_text(encoding='utf-8').replace('pdf-annotation-editor','pdf-annotation-list').replace("['new-comment','new-highlight','edit','color','quote','discard','invalid']","['list','detail','filters','filters-edited','filtered','empty','no-match','actions','delete','undo']").replace("'821c71606'","'22f94899f'")
a=capture.index("['.pdf-annotation-list'") if "['.pdf-annotation-list'" in capture else -1
old="['.pdf-annotation-list','.annotation-editor-header','.annotation-editor-context','.annotation-editor-body','.annotation-source-row','.annotation-color-row','#pdf-comment','.annotation-editor-footer','.annotation-editor-layer','.annotation-editor-dialog','.annotation-editor-dialog-header','.annotation-editor-dialog-body','.annotation-editor-dialog-footer']"
new="['.pdf-notes-panel','.pdf-notes-heading','.pdf-notes-context','.pdf-notes-body','.pdf-annotation-search','.pdf-annotation-list','.pdf-annotation-link','.pdf-annotation-detail','.pdf-annotation-filter-task','.pdf-notes-footer','.pdf-notes-layer','.pdf-notes-dialog','.pdf-notes-dialog-header','.pdf-notes-dialog-body','.pdf-notes-dialog-footer']"
assert old in capture;capture=capture.replace(old,new)
Path('scripts/capture-mobile-pdf-annotation-list-design.mjs').write_text(capture,encoding='utf-8')
